const $=id=>document.getElementById(id),D=ForestDemo;
const features=CHINA_GEOJSON.features.filter(f=>f.properties.name&&f.geometry),ids=features.map(f=>String(f.properties.adcode));
const state={region:'all',start:2000,end:2025,mode:'rate',sort:'desc'};let timer=null;
features.forEach(f=>{const o=document.createElement('option');o.value=f.properties.adcode;o.textContent=f.properties.name;$('region').append(o)});
for(let y=1990;y<=2025;y++){for(const id of ['start','end']){const o=document.createElement('option');o.value=y;o.textContent=y;$(id).append(o)}}
const name=id=>id==='all'?'全国':features.find(f=>String(f.properties.adcode)===id)?.properties.name||id;
const value=(id,y)=>id==='all'?D.national(ids,y):D.rate(id,y);
const signed=n=>(n>=0?'+':'')+n.toFixed(2);
function color(v,change=false){const a=change?(v<0?[202,140,83]:[77,131,161]):[36,92,70],b=[239,244,226],t=change?Math.min(Math.abs(v)/16,1):Math.min(v/80,1);return `rgb(${b.map((n,i)=>Math.round(n+(a[i]-n)*t)).join(',')})`}
function project(p){return [(p[0]-72)*10,(55-p[1])*12]}
function path(g){const polys=g.type==='MultiPolygon'?g.coordinates:[g.coordinates];return polys.map(poly=>poly.map(r=>r.map((p,i)=>{const q=project(p);return(i?'L':'M')+q.map(n=>n.toFixed(1)).join(',')}).join('')+'Z').join('')).join('')}
function inset(year){return '<svg x="550" y="325" width="94" height="145" viewBox="315 360 220 280"><rect x="315" y="360" width="220" height="280" fill="#fff" stroke="#a5b5a2" stroke-width="2"/>'+CHINA_GEOJSON.features.filter(f=>f.geometry).map(f=>'<path d="'+path(f.geometry)+'" fill="'+(f.properties.name?color(D.rate(String(f.properties.adcode),year)):'#8a9d88')+'" stroke="#fff" stroke-width="0.5"/>').join('')+'</svg><text x="597" y="483" text-anchor="middle" font-size="10" fill="#8a9d88">南海诸岛</text>'}
function mapSVG(year,mini=false){return `<svg viewBox="0 0 660 490" role="img" aria-label="${year}年合成数据省级地图">${features.map(f=>{const id=String(f.properties.adcode),v=state.mode==='change'&&!mini?D.change(id,state.start,year,ids):D.rate(id,year);return `<path class="province ${id===state.region?'focused':''}" data-id="${id}" d="${path(f.geometry)}" fill="${color(v,state.mode==='change'&&!mini)}" ${mini?'':`tabindex="0" role="button" aria-label="${f.properties.name}，查看示例数据"`}/>`}).join('')}${mini?'':features.filter(f=>f.properties.center&&![110000,120000,310000,810000,820000].includes(f.properties.adcode)).map(f=>{const p=project(f.properties.center);return `<text class="province-label" text-anchor="middle" x="${p[0]}" y="${p[1]}">${f.properties.name.replace(/省|市|自治区|壮族|回族|维吾尔/g,'')}</text>`}).join('')}${inset(year)}<text x="30" y="475" font-size="10" fill="#a1ad97">示意边界 · 合成数值</text></svg>`}
function selectRegion(id){state.region=id;$('region').value=id;render()}
function bindMap(){document.querySelectorAll('#map .province').forEach(p=>{p.onclick=()=>selectRegion(p.dataset.id);p.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectRegion(p.dataset.id)}};p.onmousemove=e=>{const id=p.dataset.id,t=$('tooltip');t.textContent=`${name(id)} · 合成示例\n${state.end}年 ${value(id,state.end).toFixed(2)}%\n期间变化 ${signed(D.change(id,state.start,state.end,ids))} 个百分点`;t.style.display='block';t.style.left=Math.min(e.clientX+15,window.innerWidth-220)+'px';t.style.top=Math.max(10,Math.min(e.clientY+15,window.innerHeight-100))+'px'};p.onmouseleave=()=>$('tooltip').style.display='none'})}
function trend(){const W=480,H=224,L=42,R=15,T=20,B=30,arr=Array.from({length:36},(_,i)=>({y:i+1990,v:value(state.region,i+1990)}));const lo=Math.max(0,Math.floor(Math.min(...arr.map(a=>a.v))/5)*5-5),hi=Math.ceil(Math.max(...arr.map(a=>a.v))/5)*5+5;const x=y=>L+(y-1990)/35*(W-L-R),z=v=>T+(hi-v)/(hi-lo)*(H-T-B);let grid='';for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4;grid+=`<line x1="${L}" x2="${W-R}" y1="${z(v)}" y2="${z(v)}" stroke="#e9eee3" stroke-dasharray="3 4"/><text x="${L-9}" y="${z(v)+3}" text-anchor="end" fill="#9aa78f" font-size="9">${v.toFixed(0)}%</text>`}for(const y of [1990,2000,2010,2020,2025])grid+=`<text x="${x(y)}" y="${H-8}" text-anchor="middle" font-size="9" fill="#9aa78f">${y}</text>`;const line=arr.map((p,i)=>(i?'L':'M')+x(p.y)+','+z(p.v)).join(' ');const end=value(state.region,state.end);$('trend').innerHTML=`<svg id="trendSVG" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${name(state.region)}合成森林覆盖比例时间序列"><title>合成演示数据，不代表真实森林覆盖率</title><rect width="480" height="224" fill="white"/><text x="42" y="11" font-size="9" fill="#8a9781">${name(state.region)} · 合成演示，非实际数据</text><rect x="${x(state.start)}" y="${T}" width="${x(state.end)-x(state.start)}" height="${H-T-B}" fill="#f1f5eb"/>${grid}<path d="${line}" fill="none" stroke="#3a7450" stroke-width="2.5"/>${[state.start,state.end].map(y=>`<circle cx="${x(y)}" cy="${z(value(state.region,y))}" r="4" fill="#fff" stroke="#3a7450" stroke-width="2"/>`).join('')}<text x="${Math.min(x(state.end),W-60)}" y="${z(end)-12}" font-size="11" font-family="sans-serif" fill="#3a7450">${end.toFixed(2)}%</text></svg>`}
function rankings(){const arr=ids.map(id=>({id,v:D.change(id,state.start,state.end,ids)})).sort((a,b)=>state.sort==='desc'?b.v-a.v:a.v-b.v).slice(0,8),max=Math.max(...arr.map(a=>Math.abs(a.v)),1);$('ranking').innerHTML=arr.map((a,i)=>`<button class="rank-row" data-id="${a.id}"><span class="number">${String(i+1).padStart(2,'0')}</span><span>${name(a.id).replace(/省|市|自治区|壮族|回族|维吾尔/g,'')}</span><span class="bar-track"><span class="bar" style="display:block;width:${Math.abs(a.v)/max*100}%;background:${a.v<0?'#bd8b55':'#7e9e68'}"></span></span><span class="rank-value">${signed(a.v)}</span></button>`).join('');document.querySelectorAll('.rank-row').forEach(el=>el.onclick=()=>selectRegion(el.dataset.id))}
function render(){$('start').value=state.start;$('end').value=state.end;$('yearSlider').min=state.start;$('yearSlider').value=state.end;$('sliderYear').textContent=state.end;[...$('end').options].forEach(o=>o.disabled=Number(o.value)<state.start);$('rate').innerHTML=value(state.region,state.end).toFixed(2)+'<em>%</em>';$('rateNote').textContent=`${name(state.region)} · ${state.end}年合成示例`;$('delta').innerHTML=signed(D.change(state.region,state.start,state.end,ids))+'<em>个百分点</em>';$('deltaNote').textContent=`${state.start}—${state.end} · 相同演示口径`;$('mapSubtitle').textContent=`${state.end}年 · 合成数据 · ${state.mode==='rate'?'覆盖比例（%）':'期间变化（百分点）'}`;$('trendSubtitle').textContent=`${name(state.region)} · 1990—2025 · 合成演示`;$('map').innerHTML=mapSVG(state.end);$('mapLegend').innerHTML=state.mode==='rate'?'0% <i class="gradient"></i> 80%':'−16 <i class="gradient" style="background:linear-gradient(90deg,#ca8c53,#eff4e2,#4d83a1)"></i> +16 个百分点';$('rateMode').classList.toggle('selected',state.mode==='rate');$('changeMode').classList.toggle('selected',state.mode==='change');$('compareStart').textContent=state.start+' 年';$('compareEnd').textContent=state.end+' 年';$('miniStart').innerHTML=mapSVG(state.start,true);$('miniEnd').innerHTML=mapSVG(state.end,true);bindMap();trend();rankings()}
$('region').onchange=e=>selectRegion(e.target.value);$('start').onchange=e=>{state.start=+e.target.value;state.end=Math.max(state.start,state.end);render()};$('end').onchange=e=>{state.end=+e.target.value;render()};$('yearSlider').oninput=e=>{state.end=+e.target.value;render()};$('sort').onchange=e=>{state.sort=e.target.value;rankings()};$('rateMode').onclick=()=>{state.mode='rate';render()};$('changeMode').onclick=()=>{state.mode='change';render()};
function stop(){clearInterval(timer);timer=null;$('playBtn').textContent='▶';$('playBtn').setAttribute('aria-label','播放年份')}
$('playBtn').onclick=()=>{if(timer){stop();return}if(state.end>=2025)state.end=state.start;render();$('playBtn').textContent='Ⅱ';$('playBtn').setAttribute('aria-label','暂停播放');timer=setInterval(()=>{if(state.end>=2025){stop();return}state.end++;render()},850)};
$('resetBtn').onclick=()=>{stop();Object.assign(state,{region:'all',start:2000,end:2025,mode:'rate',sort:'desc'});$('region').value='all';$('sort').value='desc';render()};
for(const id of ['sourceBtn','noticeBtn','footerSource'])$(id).onclick=()=>$('sourceDialog').showModal();$('closeDialog').onclick=()=>$('sourceDialog').close();$('sourceDialog').onclick=e=>{if(e.target===$('sourceDialog')&&e.clientX<$('sourceDialog').getBoundingClientRect().left)$('sourceDialog').close()};
function download(content,type,file){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=file;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('exportBtn').onclick=()=>{let rows=['数据性质,区域,年份,合成覆盖比例百分数'];for(let y=state.start;y<=state.end;y++)rows.push(`合成演示非实际数据,${name(state.region)},${y},${value(state.region,y).toFixed(4)}`);download('\ufeff'+rows.join('\r\n'),'text/csv;charset=utf-8',`合成示例_${name(state.region)}_${state.start}-${state.end}.csv`)};$('chartExport').onclick=()=>download($('trendSVG').outerHTML,'image/svg+xml','合成示例_趋势图.svg');render();
